      vncPassword: '',
      viewerUser: '',
      viewerPassword: '',
      kasmPathBackup: null,
      kasmPathApplied: false,
      vncTicketError: null,
      pollFallback: false,
      typedText: '',
      command: '',
      showOcr: false,
