        if (stored) return stored
      }
      return this.session
    },
    activeSessionId() {
      return this.activeSession?.id || null
    },
    kind() {
      return this.activeSession?.kind || 'linux'
    },
    kindLabel() {
      return this.activeSession?.kind_label || {
        linux: 'Linux', windows: 'Windows', macos: 'macOS', remote: 'Remote', browser: 'Browser'
      }[this.kind] || 'Computer'
    },
